let ready=false;
async function init(env){if(ready)return;await env.DB.batch([env.DB.prepare("CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT)"),env.DB.prepare("CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, data TEXT)")]);ready=true}
const API="https://discord.com/api/v10";
const RK=[["인턴",0],["사원",100],["주임",300],["대리",700],["과장",1500],["차장",3000],["부장",6000]];
const GAIN={office:[10,50],cs:[10,80],hr:[15,150],st:[20,100]};
const enc=new TextEncoder();
const rank=x=>{let r=0;RK.forEach((v,i)=>{if(x>=v[1])r=i});return RK[r][0]};
const price=m=>Math.min(3000,100+100*(m.bought||0));
async function hmac(env,v){const k=await crypto.subtle.importKey("raw",enc.encode(env.SESSION_SECRET),{name:"HMAC",hash:"SHA-256"},false,["sign"]);
 const s=await crypto.subtle.sign("HMAC",k,enc.encode(v));return[...new Uint8Array(s)].map(b=>b.toString(16).padStart(2,"0")).join("")}
const sign=async(env,v)=>v+"."+await hmac(env,v);
const unsign=async(env,s)=>{if(!s)return null;const i=s.lastIndexOf(".");const v=s.slice(0,i);return(await sign(env,v))===s?v:null};
const cookies=r=>Object.fromEntries((r.headers.get("Cookie")||"").split("; ").filter(Boolean).map(c=>{const i=c.indexOf("=");return[c.slice(0,i),c.slice(i+1)]}));
const json=(code,obj)=>new Response(JSON.stringify(obj),{status:code,headers:{"Content-Type":"application/json"}});
const getMember=async(env,id)=>{const r=await env.DB.prepare("SELECT data FROM members WHERE id=?").bind(id).first();return r?JSON.parse(r.data):null};
const putMember=(env,id,m)=>env.DB.prepare("INSERT OR REPLACE INTO members (id,data) VALUES (?,?)").bind(id,JSON.stringify(m)).run();
const getUser=async(env,id)=>{const r=await env.DB.prepare("SELECT username FROM users WHERE id=?").bind(id).first();return r?r.username:null};
function roleJob(env,ctx,id,m){
 const want=m.dept!=="none"?[rank(m.xp),m.dept]:[];const key="v2:"+want.join(":");
 if(m.synced===key)return;
 if(!env.DISCORD_BOT_TOKEN||!env.DISCORD_GUILD_ID)return;
 let roles={};try{roles=JSON.parse(env.ROLE_IDS||"{}")}catch(e){return}
 ctx.waitUntil((async()=>{let ok=true;for(const[name,rid]of Object.entries(roles)){if(!rid)continue;
  const r=await fetch(`${API}/guilds/${env.DISCORD_GUILD_ID}/members/${id}/roles/${rid}`,{method:want.includes(name)?"PUT":"DELETE",headers:{Authorization:"Bot "+env.DISCORD_BOT_TOKEN}}).catch(()=>null);
  if(!r||!r.ok){ok=false;console.log("role fail",name,r?r.status:"x",r?await r.text():"")}}
  if(ok)await env.DB.prepare("UPDATE members SET data=json_set(data,'$.synced',?) WHERE id=?").bind(key,id).run()})());
}
